/* ── cursor ──────────────────────────────────────────────── */
function Cursor() {
  const [pos, setPos] = useState({ x:-200, y:-200 });
  const [hov, setHov] = useState(false);
  useEffect(() => {
    const mv = (e) => setPos({ x:e.clientX, y:e.clientY });
    const ov = (e) => setHov(!!e.target.closest("a,button,[data-hover]"));
    window.addEventListener("mousemove", mv);
    window.addEventListener("mouseover", ov);
    return () => { window.removeEventListener("mousemove", mv); window.removeEventListener("mouseover", ov); };
  }, []);
  return (
    <motion.div style={{ position:"fixed",top:0,left:0,pointerEvents:"none",zIndex:99999,mixBlendMode:"difference" }}
      animate={{ x:pos.x-(hov?20:6), y:pos.y-(hov?20:6) }}
      transition={{ type:"spring",stiffness:600,damping:40,mass:0.4 }}>
      <motion.div animate={{ width:hov?40:12,height:hov?40:12 }}
        transition={{ type:"spring",stiffness:400,damping:30 }}
        style={{ background:"#f5f4f0",borderRadius:"50%" }} />
    </motion.div>
  );
}

