/* ── root ────────────────────────────────────────────────── */
export default function App() {
  const [scrollY, setScrollY] = useState(0);
  useEffect(() => {
    const fn = () => setScrollY(window.scrollY);
    window.addEventListener("scroll", fn, { passive:true });
    return () => window.removeEventListener("scroll", fn);
  }, []);

  return (
    <div style={{ fontFamily:"'DM Sans', sans-serif",background:"#f5f4f0",overflowX:"hidden",cursor:"none" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,wght@0,300;0,400;0,500;0,600;1,300&family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&display=swap');
        *,*::before,*::after{margin:0;padding:0;box-sizing:border-box;cursor:none!important;}
        html{scroll-behavior:smooth;}
        ::selection{background:#1a1a1a;color:#f5f4f0;}
        ::-webkit-scrollbar{width:3px;}
        ::-webkit-scrollbar-track{background:#f5f4f0;}
        ::-webkit-scrollbar-thumb{background:#1a1a1a;}
        @media(max-width:768px){*{cursor:auto!important;} nav>div:last-child{display:none!important;}}
      `}</style>
      <Cursor/>
      <Nav scrolled={scrollY>80}/>
      <Hero/>
      <Intro/>
      <Projects/>
      <About/>
      <Skills/>
      <Footer/>
    </div>
  );
}